style.css:
@-moz-document domain("google.com") {
:root {
    --my-transparency: 0.25; /* Cambia este valor (0.25 = 75% transparente) */
  }

  /* Logo de Google transparente */
  #logo,
  ntp-logo {
    opacity: var(--my-transparency) !important;
  }

  /* Barra de búsqueda transparente */
  cr-searchbox-input#input {
    opacity: var(--my-transparency) !important;
  }
}
